        api_battery_assessment == Battery_Assessment_Value.Adequate_Battery) &&
      !(In_current_phase == Lifecycle_Phase.Flying &&
        api_qualified_request == Qualified_Request.End_Flight) &&
      !(In_current_phase == Lifecycle_Phase.Ready &&
        api_qualified_request == Qualified_Request.Deactivate)) ___>:
      (current_phase == In_current_phase &&
         recovery_required == F &&
         api_selected_phase == In_current_phase &&
         api_phase_report == In_current_phase &&
         api_decision_disposition.input_fault_detected == F &&
         api_decision_disposition.recovery_pending == F)

  /** CEP-T-Case: Top-Level case contracts for lifecycle_decision_owner's compute entrypoint
    *
    * @param In_current_phase pre-state state variable
    * @param In_recovery_required pre-state state variable
    * @param current_phase post-state state variable
    * @param recovery_required post-state state variable
    * @param api_battery_assessment incoming data port
    * @param api_qualified_request incoming data port
    * @param api_decision_disposition outgoing data port
    * @param api_phase_report outgoing data port
    * @param api_selected_phase outgoing data port
    */
  @strictpure def compute_CEP_T_Case (
      In_current_phase: Drone_Lifecycle_Governor.Lifecycle_Phase.Type,
      In_recovery_required: Base_Types.Boolean,
      current_phase: Drone_Lifecycle_Governor.Lifecycle_Phase.Type,
      recovery_required: Base_Types.Boolean,
      api_battery_assessment: Drone_Lifecycle_Governor.Battery_Assessment_Value.Type,
      api_qualified_request: Drone_Lifecycle_Governor.Qualified_Request.Type,
      api_decision_disposition: Drone_Lifecycle_Governor.Decision_Disposition,
      api_phase_report: Drone_Lifecycle_Governor.Lifecycle_Phase.Type,
      api_selected_phase: Drone_Lifecycle_Governor.Lifecycle_Phase.Type): B =
    {
      val r0 = compute_case_invalid_input(current_phase, recovery_required, api_battery_assessment, api_qualified_request, api_decision_disposition, api_phase_report, api_selected_phase)
      val r1 = compute_case_recovery_blocks_replay(In_recovery_required, current_phase, recovery_required, api_battery_assessment, api_qualified_request, api_decision_disposition, api_phase_report, api_selected_phase)
      val r2 = compute_case_neutral_clears_recovery(In_recovery_required, current_phase, recovery_required, api_battery_assessment, api_qualified_request, api_decision_disposition, api_phase_report, api_selected_phase)
      val r3 = compute_case_switch_off(In_recovery_required, current_phase, recovery_required, api_battery_assessment, api_qualified_request, api_decision_disposition, api_phase_report, api_selected_phase)
      val r4 = compute_case_switch_on(In_current_phase, In_recovery_required, current_phase, recovery_required, api_battery_assessment, api_qualified_request, api_decision_disposition, api_phase_report, api_selected_phase)
      val r5 = compute_case_begin_charge(In_current_phase, In_recovery_required, current_phase, recovery_required, api_battery_assessment, api_qualified_request, api_decision_disposition, api_phase_report, api_selected_phase)
      val r6 = compute_case_end_charge(In_current_phase, In_recovery_required, current_phase, recovery_required, api_battery_assessment, api_qualified_request, api_decision_disposition, api_phase_report, api_selected_phase)
      val r7 = compute_case_activate(In_current_phase, In_recovery_required, current_phase, recovery_required, api_battery_assessment, api_qualified_request, api_decision_disposition, api_phase_report, api_selected_phase)
      val r8 = compute_case_begin_flight(In_current_phase, In_recovery_required, current_phase, recovery_required, api_battery_assessment, api_qualified_request, api_decision_disposition, api_phase_report, api_selected_phase)
      val r9 = compute_case_end_flight(In_current_phase, In_recovery_required, current_phase, recovery_required, api_battery_assessment, api_qualified_request, api_decision_disposition, api_phase_report, api_selected_phase)
      val r10 = compute_case_deactivate(In_current_phase, In_recovery_required, current_phase, recovery_required, api_battery_assessment, api_qualified_request, api_decision_disposition, api_phase_report, api_selected_phase)
      val r11 = compute_case_hold(In_current_phase, In_recovery_required, current_phase, recovery_required, api_battery_assessment, api_qualified_request, api_decision_disposition, api_phase_report, api_selected_phase)

      r0 & r1 & r2 & r3 & r4 & r5 & r6 & r7 & r8 & r9 & r10 & r11
    }

  /** CEP-Post: Compute Entrypoint Post-Condition for lifecycle_decision_owner
    *
    * @param In_current_phase pre-state state variable
    * @param In_recovery_required pre-state state variable
    * @param current_phase post-state state variable
    * @param recovery_required post-state state variable
    * @param api_battery_assessment incoming data port
    * @param api_qualified_request incoming data port
    * @param api_decision_disposition outgoing data port
    * @param api_phase_report outgoing data port
    * @param api_selected_phase outgoing data port
    */
  @strictpure def compute_CEP_Post (
      In_current_phase: Drone_Lifecycle_Governor.Lifecycle_Phase.Type,
      In_recovery_required: Base_Types.Boolean,
      current_phase: Drone_Lifecycle_Governor.Lifecycle_Phase.Type,
      recovery_required: Base_Types.Boolean,
      api_battery_assessment: Drone_Lifecycle_Governor.Battery_Assessment_Value.Type,
      api_qualified_request: Drone_Lifecycle_Governor.Qualified_Request.Type,
      api_decision_disposition: Drone_Lifecycle_Governor.Decision_Disposition,
      api_phase_report: Drone_Lifecycle_Governor.Lifecycle_Phase.Type,
      api_selected_phase: Drone_Lifecycle_Governor.Lifecycle_Phase.Type): B =
    {
      // CEP-Guar: guarantee clauses of lifecycle_decision_owner's compute entrypoint
      val r0 = compute_CEP_T_Guar (current_phase, recovery_required, api_phase_report, api_selected_phase)

      // CEP-T-Case: case clauses of lifecycle_decision_owner's compute entrypoint
      val r1 = compute_CEP_T_Case (In_current_phase, In_recovery_required, current_phase, recovery_required, api_battery_assessment, api_qualified_request, api_decision_disposition, api_phase_report, api_selected_phase)

      r0 & r1
    }

  /** CEP-Post: Compute Entrypoint Post-Condition for lifecycle_decision_owner via containers
    *
    * @param pre Container holding the values of incoming ports and the pre-state values of state variables
    * @param post Container holding the values of outgoing ports and the post-state values of state variables
    */
  @strictpure def compute_CEP_Post_Container(
      pre: Lifecycle_Decision_Owner_governor_process_lifecycle_decision_owner_PreState_Container_PS,
      post: Lifecycle_Decision_Owner_governor_process_lifecycle_decision_owner_PostState_Container_PS): B =
    compute_CEP_Post(
      In_current_phase = pre.In_current_phase,
      In_recovery_required = pre.In_recovery_required,
      current_phase = post.current_phase,
      recovery_required = post.recovery_required,
      api_battery_assessment = pre.api_battery_assessment,
      api_qualified_request = pre.api_qualified_request,
      api_decision_disposition = post.api_decision_disposition,
      api_phase_report = post.api_phase_report,
      api_selected_phase = post.api_selected_phase)
}
